// ─── Prepare Judge Prompt ───
// Creates an expert judge prompt with 5 scoring criteria
const rawInput = $input.first().json;
const input = rawInput.body || rawInput;

const question = input.question || '';
const sector = input.sector || 'unknown';
const pipeline = input.pipeline || 'unknown';
const response = input.response || '';
const sources = input.sources || [];
const latencyMs = input.latency_ms || 0;
const space = input.space || 'unknown';
const executionId = input.execution_id || 'exec-' + Date.now();

// Truncate response for judging (keep first 3000 chars)
const responseExcerpt = response.substring(0, 3000);

// Format sources for the prompt
const sourcesText = Array.isArray(sources) && sources.length > 0
  ? sources.map((s, i) => {
      if (typeof s === 'string') return `[${i+1}] ${s}`;
      return `[${i+1}] ${s.source || s.name || s.title || JSON.stringify(s).substring(0, 200)}`;
    }).join('\n')
  : 'No sources provided';

// Sector context for the judge
const SECTOR_CONTEXT = {
  finance: 'Financial sector: expects terms like IFRS, EBITDA, BFR, marge brute, ratio de solvabilite, credit-bail, amortissement, tresorerie, bilan, compte de resultat. Professional French financial terminology.',
  btp: 'Construction/BTP sector: expects terms like DTU, Eurocode, CCTP, RE2020, permis de construire, lot technique, maitre d\'ouvrage, BOAMP, NF EN, parasismique. Professional French construction terminology.',
  juridique: 'Legal/Juridique sector: expects terms like prescription, code civil, jurisprudence, RGPD, licenciement, SAS/SARL, greffe, tribunal, assignation, clause resolutoire. Professional French legal terminology.',
  industrie: 'Industrial sector: expects terms like ISO 9001, AMDEC, lean manufacturing, FDS, maintenance preventive, TPM, Six Sigma, gamme de fabrication, cahier des charges. Professional French industrial terminology.'
};

const PIPELINE_CONTEXT = {
  standard: 'Standard RAG pipeline: vector search + BM25 + reranking. Should provide well-sourced, comprehensive answers.',
  graph: 'Graph RAG pipeline: entity-relationship based retrieval from Neo4j. Should excel at relational questions.',
  quantitative: 'Quantitative pipeline: SQL-based financial data retrieval. Should provide precise numerical answers.',
  orchestrator: 'Orchestrator: routes to the best pipeline. Should pick the right engine and provide optimal answers.'
};

const sectorCtx = SECTOR_CONTEXT[sector.toLowerCase()] || `Sector: ${sector}. Use appropriate professional terminology.`;
const pipelineCtx = PIPELINE_CONTEXT[pipeline.toLowerCase()] || `Pipeline: ${pipeline}.`;

// Detect question language
const frenchIndicators = /[àâäéèêëïîôùûüÿçœæ]|\b(le|la|les|des|du|un|une|est|sont|dans|pour|avec|sur|par|qui|que|quel|quels|quelle|quelles|comment|pourquoi)\b/i;
const questionLang = frenchIndicators.test(question) ? 'French' : 'English';

const prompt = `You are an expert evaluation judge for a RAG (Retrieval-Augmented Generation) system specialized in ${sector} sector.

## Context
- Sector: ${sector.toUpperCase()}
- ${sectorCtx}
- Pipeline: ${pipeline}
- ${pipelineCtx}
- Question language detected: ${questionLang}
- Response latency: ${latencyMs}ms

## Question Asked
${question}

## Response to Evaluate
${responseExcerpt}

## Sources Cited
${sourcesText}

## Scoring Criteria (score each 0-20)

1. **accuracy** (0-20): Does the response correctly and factually answer the question? Penalize hallucinations, incorrect facts, or misleading information heavily.

2. **completeness** (0-20): Is the answer thorough with proper depth? Does it cover the main aspects of the question? A one-line answer to a complex question should score low.

3. **terminology** (0-20): Does the response use correct sector-specific professional terms? For ${sector}, expected terminology includes domain-specific jargon, acronyms, and technical references.

4. **sources** (0-20): Are sources cited in the response? Are they relevant to the question? Are specific documents/sections referenced? No sources = score 0-5 max.

5. **language** (0-20): Does the response use the same language as the question? The question is in ${questionLang}. A response in a different language should score 0-5. Also assess grammar and clarity.

## Instructions
- Be a STRICT judge. Do not give high scores easily.
- An empty or error response = all scores 0.
- A generic response without sector expertise = max 10 per criterion.
- Only truly expert-level responses with proper sourcing deserve 16+.
- Provide a brief reasoning for each score.

Respond ONLY with valid JSON in this exact format:
{
  "accuracy": <0-20>,
  "completeness": <0-20>,
  "terminology": <0-20>,
  "sources": <0-20>,
  "language": <0-20>,
  "reasoning": {
    "accuracy": "brief explanation",
    "completeness": "brief explanation",
    "terminology": "brief explanation",
    "sources": "brief explanation",
    "language": "brief explanation"
  },
  "overall_comment": "1-2 sentence overall assessment"
}`;

return [{
  json: {
    prompt,
    question,
    sector,
    pipeline,
    response_excerpt: responseExcerpt,
    sources_text: sourcesText,
    question_lang: questionLang,
    latency_ms: latencyMs,
    space,
    execution_id: executionId,
    original_sources: sources,
    original_response_length: response.length
  }
}];

