// ─── Parse Judge Response ───
// Extracts scores from LLM response, handles various formats
const llmResponse = $input.first().json;
const prevData = $node['Prepare Judge Prompt'].json;

let scores = null;
let parseError = null;
let rawContent = '';

try {
  // Extract content from LLM response
  const choices = llmResponse.choices || [];
  if (choices.length > 0) {
    rawContent = choices[0].message?.content || '';
  }

  if (!rawContent && llmResponse.error) {
    throw new Error('LLM error: ' + (typeof llmResponse.error === 'string' ? llmResponse.error : JSON.stringify(llmResponse.error)));
  }

  if (rawContent) {
    let cleaned = rawContent.trim();

    // Handle markdown JSON blocks
    if (cleaned.includes('```json')) {
      cleaned = cleaned.split('```json')[1].split('```')[0].trim();
    } else if (cleaned.includes('```')) {
      cleaned = cleaned.split('```')[1].split('```')[0].trim();
    }

    // Handle potential leading/trailing text around JSON
    const jsonStart = cleaned.indexOf('{');
    const jsonEnd = cleaned.lastIndexOf('}');
    if (jsonStart !== -1 && jsonEnd !== -1 && jsonEnd > jsonStart) {
      cleaned = cleaned.substring(jsonStart, jsonEnd + 1);
    }

    scores = JSON.parse(cleaned);
  }
} catch (err) {
  parseError = `Parse error: ${err.message}. Raw: ${rawContent.substring(0, 500)}`;
}

// Extract individual scores with defaults
const accuracy = Math.min(20, Math.max(0, parseInt(scores?.accuracy) || 0));
const completeness = Math.min(20, Math.max(0, parseInt(scores?.completeness) || 0));
const terminology = Math.min(20, Math.max(0, parseInt(scores?.terminology) || 0));
const sourcesScore = Math.min(20, Math.max(0, parseInt(scores?.sources) || 0));
const language = Math.min(20, Math.max(0, parseInt(scores?.language) || 0));

const totalScore = accuracy + completeness + terminology + sourcesScore + language;

// Classification
let classification = 'BAD';
if (totalScore >= 75) classification = 'GOOD';
else if (totalScore >= 50) classification = 'MEDIUM';

// Build judge reasoning
const reasoning = scores?.reasoning || {};
const overallComment = scores?.overall_comment || '';
const judgeReasoning = [
  `Accuracy(${accuracy}/20): ${reasoning.accuracy || 'N/A'}`,
  `Completeness(${completeness}/20): ${reasoning.completeness || 'N/A'}`,
  `Terminology(${terminology}/20): ${reasoning.terminology || 'N/A'}`,
  `Sources(${sourcesScore}/20): ${reasoning.sources || 'N/A'}`,
  `Language(${language}/20): ${reasoning.language || 'N/A'}`,
  overallComment ? `Overall: ${overallComment}` : ''
].filter(Boolean).join(' | ');

return [{
  json: {
    // Scores
    total_score: totalScore,
    accuracy_score: accuracy,
    completeness_score: completeness,
    terminology_score: terminology,
    sources_score: sourcesScore,
    language_score: language,
    classification,
    judge_reasoning: judgeReasoning.substring(0, 2000),
    overall_comment: overallComment,

    // Context from input
    question: prevData.question,
    sector: prevData.sector,
    pipeline: prevData.pipeline,
    response_excerpt: prevData.response_excerpt?.substring(0, 1000) || '',
    space: prevData.space,
    execution_id: prevData.execution_id,
    latency_ms: prevData.latency_ms,
    question_lang: prevData.question_lang,
    original_response_length: prevData.original_response_length,
    sources_count: Array.isArray(prevData.original_sources) ? prevData.original_sources.length : 0,
    judged_at: new Date().toISOString(),

    // Debug
    parse_error: parseError,
    raw_scores: scores
  }
}];

// ─── Build final response for BAD executions (with failure analysis) ───
const judgeData = $node['Parse Judge Response'].json;
const analyzerResponse = $input.first().json;

let failureAnalysis = null;
let analyzeError = null;

try {
  const choices = analyzerResponse.choices || [];
  let rawContent = '';
  if (choices.length > 0) {
    rawContent = choices[0].message?.content || '';
  }

  if (rawContent) {
    let cleaned = rawContent.trim();
    // Handle markdown JSON blocks
    if (cleaned.includes('```json')) {
      cleaned = cleaned.split('```json')[1].split('```')[0].trim();
    } else if (cleaned.includes('```')) {
      cleaned = cleaned.split('```')[1].split('```')[0].trim();
    }
    const jsonStart = cleaned.indexOf('{');
    const jsonEnd = cleaned.lastIndexOf('}');
    if (jsonStart !== -1 && jsonEnd !== -1) {
      cleaned = cleaned.substring(jsonStart, jsonEnd + 1);
    }
    failureAnalysis = JSON.parse(cleaned);
  }
} catch (err) {
  analyzeError = 'Pattern analyzer parse error: ' + err.message;
}

return [{
  json: {
    total_score: judgeData.total_score,
    classification: judgeData.classification,
    scores: {
      accuracy: judgeData.accuracy_score,
      completeness: judgeData.completeness_score,
      terminology: judgeData.terminology_score,
      sources: judgeData.sources_score,
      language: judgeData.language_score
    },
    judge_reasoning: judgeData.judge_reasoning,
    overall_comment: judgeData.overall_comment,
    failure_analysis: failureAnalysis || {
      failure_type: 'unknown',
      root_cause: analyzeError || 'Could not analyze failure',
      suggested_fix: 'Manual investigation required',
      affected_node: 'unknown',
      priority: 'MEDIUM',
      pattern_indicator: 'unknown_' + judgeData.sector
    },
    metadata: {
      question: judgeData.question,
      sector: judgeData.sector,
      pipeline: judgeData.pipeline,
      space: judgeData.space,
      execution_id: judgeData.execution_id,
      latency_ms: judgeData.latency_ms,
      judged_at: judgeData.judged_at
    }
  }
}];

// ─── Build final response for GOOD/MEDIUM executions (no failure analysis) ───
const judgeData = $node['Parse Judge Response'].json;

return [{
  json: {
    total_score: judgeData.total_score,
    classification: judgeData.classification,
    scores: {
      accuracy: judgeData.accuracy_score,
      completeness: judgeData.completeness_score,
      terminology: judgeData.terminology_score,
      sources: judgeData.sources_score,
      language: judgeData.language_score
    },
    judge_reasoning: judgeData.judge_reasoning,
    overall_comment: judgeData.overall_comment,
    failure_analysis: null,
    metadata: {
      question: judgeData.question,
      sector: judgeData.sector,
      pipeline: judgeData.pipeline,
      space: judgeData.space,
      execution_id: judgeData.execution_id,
      latency_ms: judgeData.latency_ms,
      judged_at: judgeData.judged_at
    }
  }
}];
